  if($rawName -cin @('Bark_NormalTree','Leaves_TwistedTree','Leaves_NormalTree')){$suffixes+=@('cutout_disabled')}
  if($rawName -ceq 'Bark_NormalTree'){$suffixes+=@('alpha_witness_stock','alpha_witness_converted','alpha_witness_disabled')}
  foreach($suffix in $suffixes){$path=SafeChild $Directory ($item.label+'_'+$suffix+'.png');if(-not(Test-Path -LiteralPath $path -PathType Leaf) -or (Get-Item -LiteralPath $path).Length -le 0){throw 'Expected material image absent'}}
 }
}
function IdentityMismatches($Observed,$Expected){
 $fields=@()
 if([string]::IsNullOrWhiteSpace([string]$Observed.executable) -or $Observed.executable -ine $Expected.executable){$fields+=@('executable')}
 if($null -eq $Observed.parent -or [long]$Observed.parent -ne [long]$Expected.parent){$fields+=@('parent')}
 if($null -eq $Observed.created_utc){$fields+=@('creation_time_missing')}elseif([math]::Abs(([DateTime]$Observed.created_utc-[DateTime]$Expected.created_utc).TotalSeconds) -gt 1){$fields+=@('creation_time')}
 return $fields
}
